def task_func(myString, API_KEY):
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    urls = re.findall(url_pattern, myString)

    domains = set()
    for url in urls:
        domain = urllib.parse.urlparse(url).netloc
        if domain:
            domains.add(domain)

    geolocation_results = {}
    for domain in domains:
        try:
            api_url = f"http://pro.ip-api.com/json/{domain}?key={API_KEY}"
            response = requests.get(api_url)
            if response.status_code == 200:
                geolocation_results[domain] = json.loads(response.text)
            else:
                geolocation_results[domain] = None
        except Exception:
            geolocation_results[domain] = None

    return geolocation_results

