                data = json.loads(post_data)
                if 'data' not in data:
                    raise ValueError("Missing data key")

                self.send_response(200)
                self.send_header('Content-Type', 'application/json')
                self.end_headers()
                response = {
                    "status": "success",
                    "message": "Data received successfully."
                }
