import os
def task_func(directory, string):
    def search_in_data(data, target):
        if isinstance(data, dict):
            for k, v in data.items():
                if k == target or search_in_data(v, target):
                    return True
        elif isinstance(data, list):
            for item in data:
                if search_in_data(item, target):
                    return True
        elif str(data) == target:
            return True
        return False

    matched_files = []
    search_pattern = os.path.join(directory, '**', '*.json')
    json_files = glob(search_pattern, recursive=True)

    for file_path in json_files:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
                if search_in_data(data, string):
                    matched_files.append(file_path)
        except (json.JSONDecodeError, IOError):
            continue

    return matched_files

